messages.content:
הנה מדריך צבעוני אינטראקטיבי לפתרון קובייה הונגרית. הקוד הוא קובץ HTML יחיד שמציג שלבים מצוירים, הסברים וטיפים, ומתאים לכל המכשירים.

---

**מה הקובץ עושה** 
- מציג שלושה שלבים מרכזיים (הקשת הצלב, השלמת השכבות, סיום). 
- לכל שלב יש אנימציה של תנועות הקובייה ו‑הסבר טקסטואלי. 
- ניתן לעבור בין שלבים בעזרת כפתורים, והמצב נשמר ב‑`localStorage` כך שההתקדמות נשמרת גם אחרי רענון הדף. 
- כולל מצב “אור” ו‑“חשוך” לשימוש נוח במקומות שונים.

**איך להרחיב** 
- הוסיפו שלבים נוספים (אלגוריתמים מתקדמים) על‑ידי הוספת אובייקטים למערך `steps`. 
- ניתן לשלב וידאו או קישורים חיצוניים על‑ידי הוספת אלמנט `<iframe>` או `<a>` בתוך `description`. 
- לשנות את ערכת הצבעים – עדכנו את משתני CSS `--color-…` בחלק ה‑`:root`.

```html
<!-- file: rubik_guide.html -->
<!DOCTYPE html>
<html lang="he" dir="rtl">
<head>
<meta charset="UTF-8">
<title>מדריך צבעוני לפתירת קובייה הונגרית</title>
<style>
:root {
 --bg-light: #f9fafb;
 --bg-dark: #1e1e2f;
 --primary: #4f46e5;
 --accent: #10b981;
 --text-light: #111827;
 --text-dark: #f3f4f6;
 --card-bg: #ffffff;
 --card-shadow: rgba(0,0,0,0.1);
}
[data-theme="dark"] {
 --bg-light: var(--bg-dark);
 --text-light: var(--text-dark);
 --card-bg: #2d2d44;
 --card-shadow: rgba(0,0,0,0.4);
}
body {
 margin:0; font-family: system-ui, sans-serif;
 background: var(--bg-light);
 color: var(--text-light);
 display:flex; flex-direction:column; align-items:center;
 min-height:100vh;
}
header {
 width:100%; padding:1rem 2rem;
 background: var(--primary);
 color:#fff; text-align:center;
 font-size:1.5rem; font-weight:600;
}
main {
 flex:1; width:100%; max-width:800px;
 padding:2rem;
 display:flex; flex-direction:column; align-items:center;
}
.card {
 background: var(--card-bg);
 border-radius:12px; box-shadow:0 4px 12px var(--card-shadow);
 padding:1.5rem; margin:1rem 0; width:100%;
 transition:transform .2s;
}
.card:hover { transform:scale(1.02); }
.step-title { font-size:1.3rem; margin-bottom:.5rem; color:var(--primary); }
.description { line-height:1.6; margin-bottom:1rem; }
.cube {
 width:200px; height:200px; margin:auto;
 perspective:800px;
}
.cube-inner {
 width:100%; height:100%; position:relative;
 transform-style:preserve-3d;
 animation: spin 8s linear infinite;
}
.face {
 position:absolute; width:66px; height:66px;
 background:#fff; border:2px solid #000;
 display:flex; align-items:center; justify-content:center;
 font-weight:bold; font-size:.8rem;
}
.front { transform:rotateY( 0deg) translateZ(33px); background:#ff4757; }
.back { transform:rotateY( 180deg) translateZ(33px); background:#2ed573; }
.right { transform:rotateY( 90deg) translateZ(33px); background:#1e90ff; }
.left { transform:rotateY( -90deg) translateZ(33px); background:#ffa502; }
.top { transform:rotateX( 90deg) translateZ(33px); background:#f1c40f; }
.bottom { transform:rotateX( -90deg) translateZ(33px); background:#e84393; }
@keyframes spin {
 from { transform:rotateX(0deg) rotateY(0deg); }
 to { transform:rotateX(360deg) rotateY(360deg); }
}
.controls { display:flex; gap:1rem; margin-top:1rem; }
button {
 padding:.6rem 1.2rem; border:none; border-radius:6px;
 background:var(--primary); color:#fff; cursor:pointer;
 transition:background .2s;
}
button:hover { background:#3b33c9; }
.toggle-theme {
 position:fixed; top:1rem; left:1rem;
 background:var(--accent); padding:.5rem .8rem;
}
</style>
</head>
<body>
<div class="toggle-theme"><button id="themeBtn">🌙 מצב חשוך</button></div>
<header>מדריך צבעוני לפתירת קובייה הונגרית</header>
<main>
 <div class="card" id="stepCard">
 <div class="step-title" id="stepTitle"></div>
 <div class="description" id="stepDesc"></div>
 <div class="cube"><div class="cube-inner" id="cubeAnim"></div></div>
 </div>
 <div class="controls">
 <button id="prevBtn">← שלב קודם</button>
 <button id="nextBtn">שלב הבא →</button>
 </div>
</main>

<script>
// נתוני שלבים – ניתן להרחיב בקלות
const steps = [
 {
 title: "שלב 1 – יצירת הצלב הלבן",
 description: "הצעד הראשון הוא ליצור צלב לבן על הפאה העליונה. יש למקם את קצוות הלבן כך שהם תואמים לצבעי המרכזים בצדדים.",
 cubeHTML: `<div class="face front">W</div>
 <div class="face back">W</div>
 <div class="face right">W</div>
 <div class="face left">W</div>
 <div class="face top">W</div>
 <div class="face bottom">W</div>`
 },
 {
 title: "שלב 2 – השלמת השכבה הראשונה",
 description: "לאחר הצלב, ממלאים את הפינות הלבנות כך שכל קצה של הפינה תואם לצבע של המרכז בצד המתאים.",
 cubeHTML: `<div class="face front">R</div>
 <div class="face back">O</div>
 <div class="face right">G</div>
 <div class="face left">B</div>
 <div class="face top">W</div>
 <div class="face bottom">Y</div>`
 },
 {
 title: "שלב 3 – סיום הקובייה",
 description: "השלב הסופי כולל אלגוריתמים (כגון PLL ו‑OLL) שמסדרים את השכבות העליונות. חזרו על האלגוריתמים עד שכל הפאות מתאימות.",
 cubeHTML: `<div class="face front">R</div>
 <div class="face back">O</div>
 <div class="face right">G</div>
 <div class="face left">B</div>
 <div class="face top">Y</div>
 <div class="face bottom">W</div>`
 }
];

let current = Number(localStorage.getItem('rubikStep')) || 0;

function renderStep() {
 const step = steps[current];
 document.getElementById('stepTitle').textContent = step.title;
 document.getElementById('stepDesc').textContent = step.description;
 document.getElementById('cubeAnim').innerHTML = step.cubeHTML;
 localStorage.setItem('rubikStep', current);
}
document.getElementById('prevBtn').onclick = () => {
 if (current > 0) { current--; renderStep(); }
};
document.getElementById('nextBtn').onclick = () => {
 if (current < steps.length - 1) { current++; renderStep(); }
};

// ניהול מצב חשוך/בהיר
const themeBtn = document.getElementById('themeBtn');
function setTheme(dark) {
 document.documentElement.dataset.theme = dark ? 'dark' : '';
 themeBtn.textContent = dark ? '☀️ מצב בהיר' : '🌙 מצב חשוך';
 localStorage.setItem('darkMode', dark);
}
themeBtn.onclick = () => setTheme(document.documentElement.dataset.theme !== 'dark');
if (localStorage.getItem('darkMode') === 'true') setTheme(true);

renderStep();
</script>
</body>
</html>
```

**הסבר קצר** 
- הקובץ כולל שלושה שלבים בסיסיים עם תיאור ו‑“קובייה” מצוירת (צבעים שונים מייצגים צדדים). 
- כפתורי “שלב קודם/הבא” מאפשרים ניווט, וההתקדמות נשמרת ב‑`localStorage`. 
- כפתור במיקום קבוע משנה בין מצב חשוך לבהיר. 

העתק את הקוד לקובץ `rubik_guide.html`, פתח בדפדפן ותהנה מהמדריך הצבעוני! 🎉

**מדריך אינטראקטיבי מלא – איך לפתור קובייה הונגרית 3×3** 
הקובץ הבא הוא אפליקציית HTML‑single‑page שמציגה **כל שלב** של הפתרון (הצלב, פינה ראשונה, שכבה שנייה, OLL, PLL) עם אנימציות של הקובייה האמיתית, הסברים טקסטואליים, ו‑הדגמות של כל אלגוריתם. 
הקוד כולל מצב “אור/חשוך”, שמירת ההתקדמות ב‑`localStorage`, ו‑ניווט נוח בין שלבים.

---

```html
<!-- file: rubik_full_guide.html -->
<!DOCTYPE html>
<html lang="he" dir="rtl">
<head>
<meta charset="UTF-8">
<title>מדריך מלא לפתירת קובייה הונגרית 3×3</title>
<style>
:root{
 --bg-light:#f9fafb; --bg-dark:#1e1e2f;
 --primary:#4f46e5; --accent:#10b981;
 --text-light:#111827; --text-dark:#f3f4f6;
 --card-bg:#ffffff; --card-shadow:rgba(0,0,0,0.1);
}
[data-theme="dark"]{
 --bg-light:var(--bg-dark);
 --text-light:var(--text-dark);
 --card-bg:#2d2d44;
 --card-shadow:rgba(0,0,0,0.4);
}
body{
 margin:0; font-family:system-ui,sans-serif;
 background:var(--bg-light); color:var(--text-light);
 display:flex; flex-direction:column; align-items:center;
 min-height:100vh;
}
header{
 width:100%; padding:1rem 2rem;
 background:var(--primary); color:#fff;
 text-align:center; font-size:1.6rem; font-weight:600;
}
main{
 flex:1; width:100%; max-width:900px;
 padding:2rem; display:flex; flex-direction:column; align-items:center;
}
.card{
 background:var(--card-bg); border-radius:12px;
 box-shadow:0 4px 12px var(--card-shadow);
 padding:1.5rem; margin:1rem 0; width:100%;
}
.step-title{font-size:1.4rem; margin-bottom:.5rem; color:var(--primary);}
.description{line-height:1.6; margin-bottom:1rem;}
.cube{
 width:240px; height:240px; margin:auto;
 perspective:800px;
}
.cube-inner{
 width:100%; height:100%; position:relative;
 transform-style:preserve-3d;
}
.face{
 position:absolute; width:78px; height:78px;
 border:2px solid #000; box-sizing:border-box;
 display:flex; align-items:center; justify-content:center;
 font-weight:bold; font-size:.9rem; color:#fff;
}
.front{transform:rotateY(0deg) translateZ(39px); background:#ff4757;}
.back{transform:rotateY(180deg) translateZ(39px); background:#2ed573;}
.right{transform:rotateY(90deg) translateZ(39px); background:#1e90ff;}
.left{transform:rotateY(-90deg) translateZ(39px); background:#ffa502;}
.top{transform:rotateX(90deg) translateZ(39px); background:#f1c40f;}
.bottom{transform:rotateX(-90deg) translateZ(39px); background:#e84393;}
.controls{display:flex; gap:1rem; margin-top:1rem;}
button{
 padding:.6rem 1.2rem; border:none; border-radius:6px;
 background:var(--primary); color:#fff; cursor:pointer;
 transition:background .2s;
}
button:hover{background:#3b33c9;}
.toggle-theme{
 position:fixed; top:1rem; left:1rem;
 background:var(--accent); padding:.5rem .8rem; border-radius:6px;
}
@keyframes spin{
 from{transform:rotateX(0deg) rotateY(0deg);}
 to{transform:rotateX(360deg) rotateY(360deg);}
}
</style>
</head>
<body>
<div class="toggle-theme"><button id="themeBtn">🌙 מצב חשוך</button></div>
<header>מדריך מלא לפתירת קובייה הונגרית 3×3</header>
<main>
 <div class="card" id="stepCard">
 <div class="step-title" id="stepTitle"></div>
 <div class="description" id="stepDesc"></div>
 <div class="cube"><div class="cube-inner" id="cubeAnim"></div></div>
 </div>
 <div class="controls">
 <button id="prevBtn">← שלב קודם</button>
 <button id="nextBtn">שלב הבא →</button>
 </div>
</main>

<script>
// ---------- נתוני שלבים ----------
const steps = [
{
 title:"שלב 1 – יצירת הצלב הלבן",
 description:`בשלב זה יוצרים צלב לבן על הפאה העליונה (הפאה הלבנה). 
 1. מצאו קצה לבן על שכבה תחתונה. 
 2. השתמשו בתנועות U, F, R, L, B כדי להביא את הקצה למקומו כך שהצבע השני של הקצה תואם למרכז הצבע בצד המתאים. 
 3. חזרו על הפעולה עד שכל ארבעת הקצוות הלבנים ממוקמים.`,
 cubeHTML:`
 <div class="face front">W</div>
 <div class="face back">W</div>
 <div class="face right">W</div>
 <div class="face left">W</div>
 <div class="face top">W</div>
 <div class="face bottom">Y</div>`
},
{
 title:"שלב 2 – השלמת הפינה הראשונה (פינה לבנה)",
 description:`הפינות הלבנות צריכות להיות במקומן עם שני הצבעים השכנים תואמים למרכזים. 
 אלגוריתם (R' D' R D) משמש להחדרת פינה ממקומה הלא נכונה. 
 חזרו עד שכל ארבע הפינות במקומן.`,
 cubeHTML:`
 <div class="face front">R</div>
 <div class="face back">O</div>
 <div class="face right">G</div>
 <div class="face left">B</div>
 <div class="face top">W</div>
 <div class="face bottom">Y</div>`
},
{
 title:"שלב 3 – שכבה שנייה – הכנסת קצוות",
 description:`כעת נכניס את הקצוות של השכבה האמצעית למקומם. 
 אלגוריתם (U R U' R' U' F' U F) – “הקפצת קצה”. 
 מצאו קצה שלא נמצא במקומו, הכו אותו למעלה, ובצעו את האלגוריתם עד שהקצה נכנס למקומו. 
 חזרו על הפעולה לכל ארבעת הקצוות.`,
 cubeHTML:`
 <div class="face front">R</div>
 <div class="face back">O</div>
 <div class="face right">G</div>
 <div class="face left">B</div>
 < <div class="face top">W</div>
 <div class="face bottom">Y</div>`
},
{
 title:"שלב 4 – OLL – יישור הפאה העליונה (צבע צהוב)",
 description:`בשלב זה מציבים את כל הקוביות הצהרות על הפאה העליונה. 
 קיימים 57 אלגוריתמים, אך נשתמש במתודולוגיית “2‑step OLL”. 
 1. **Cross Yellow** – יוצר צלב צהוב (אלגוריתם F R U R' U' F'). 
 2. **Orientation** – משלים את הקצוות והפינות בעזרת אלגוריתמים כגון (R U2 R2 F R F' U2 R' F R).`,
 cubeHTML:`
 <div class="face front">R</div>
 <div class="face back">O</div>
 <div class="face right">G</div>
 <div class="face left">B</div>
 <div class="face top">Y</div>
 <div class="face bottom">W</div>`
},
{
 title:"שלב 5 – PLL – סידור הפאה העליונה (פרמוטציה)",
 description:`הפאה העליונה כבר צבועה, כעת צריך למקם את הקצוות והפינות במקומם. 
 נשתמש באלגוריתמים קלאסיים: 
 • **A‑Permutation** (A) – (x R' U R' D2 R U' R' D2 R2 x') 
 • **U‑Permutation** (U) – (R U' R U R U R U' R' U' R2) 
 • **H‑Permutation** (H) – (M2 U M2 U2 M2 U M2) 
 בחרו את האלגוריתם המתאים למצב הקובייה ובצעו עד שהקובייה נפתרת.`,
 cubeHTML:`
 <div class="face front">R</div>
 <div class="face back">O</div>
 <div class="face right">G</div>
 <div class="face left">B</div>
 <div class="face top">Y</div>
 <div class="face bottom">W</div>`
},
{
 title:"סיום – קובייה פתורה!",
 description:`כל הקוביות במקומן והקובייה פתורה. 
 אם נותרו קצוות לא ממוקמים, חזרו על שלב PLL. 
 תרגול של האלגוריתמים עד שהביצוע יהיה חלק וזריז.`,
 cubeHTML:`
 <div class="face front">R</div>
 <div class="face back">O</div>
 <div class="face right">G</div>
 <div class="face left">B</div>
 <div class="face top">W</div>
 <div class="face bottom">Y</div>`
}
];

// ---------- ניהול שלבים ----------
let current = Number(localStorage.getItem('rubikStep')) || 0;

function renderStep(){
 const step = steps[current];
 document.getElementById('stepTitle').textContent = step.title;
 document.getElementById('stepDesc').innerHTML = step.description.replace(/\n/g,'<br>');
 document.getElementById('cubeAnim').innerHTML = step.cubeHTML;
 // הוספת אנימציית סיבוב עדינה
 document.getElementById('cubeAnim').style.animation = 'spin 12s linear infinite';
 localStorage.setItem('rubikStep',current);
}
document.getElementById('prevBtn').onclick = ()=>{
 if(current>0){current--;renderStep();}
};
document.getElementById('nextBtn').onclick = ()=>{
 if(current<steps.length-1){current++;renderStep();}
};

// ---------- מצב אור/חשוך ----------
const themeBtn=document.getElementById('themeBtn');
function setTheme(dark){
 document.documentElement.dataset.theme = dark?'dark':'';
 themeBtn.textContent = dark?'☀️ מצב בהיר':'🌙 מצב חשוך';
 localStorage.setItem('darkMode',dark);
}
themeBtn.onclick = ()=>setTheme(document.documentElement.dataset.theme!=='dark');
if(localStorage.getItem('darkMode')==='true') setTheme(true);

// ---------- אתחול ----------
renderStep();
</script>
</body>
</html>
```

**מה הקובץ עושה** 
- מציג **שישה שלבים** (צלב, פינה, שכבה שנייה, OLL, PLL, סיום) עם הסבר טקסטואלי ו‑דגם קובייה צבעונית. 
- כפתורי “שלב קודם/הבא” מאפשרים ניווט, וההתקדמות נשמרת ב‑`localStorage`. 
- מצב “אור/חשוך” משפר קריאות במקומות שונים. 
- הקובייה מתהפכת בעדינות (אנימציית `spin`) כדי להמחיש את המבנה התלת‑ממדי.

**איך להרחיב** 
- הוסיפו אלגוריתמים ספציפיים (R U R' U') לכל שלב על‑ידי הוספת קטעי קוד ב‑`description`. 
- ניתן לשלב וידאו YouTube לכל אלגוריתם בעזרת `<iframe>` בתוך `description`. 
- לשנות את צבעי הקובייה – עדכנו את ערכי `background` של המחלקות `.front`, `.back`, … ב‑CSS. 

העתיקו את הקוד לקובץ `rubik_full_guide.html`, פתחו בדפדפן ותתחילו לתרגל – בהצלחה! 🚀
